    id: "bus-2022-hl-s1-q12", topicId: "business-3-18", conceptId: "paye-calculation-with-tax-credits",
    section: "1", questionRef: "2022 HL Section 1 Q12",
    stem: "Kellie Murphy started a new job. She registered her details on the revenue website my account. Kellie has a salary of €42,600. PAYE is to be calculated as 20% on the first €36,800 and 40% on the balance. Kellie has the following tax credits; personal tax credit €1,700, employee tax credit €1,700.",
    questionText: "Calculate the amount of PAYE Kellie Murphy will pay annually. Show your workings.",
    tariffModel: {"kind":"fixed","notation":"(4,4,2)","answer":3,"ofParts":null,"perPart":null}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Gross PAYE — 36,800 x0.20 = 7,360", marks: 1 },
    { id: "r-2", kind: "point", verbatim: "Balance = (42,600-36,800) = 5,800", marks: 1 },
    { id: "r-3", kind: "allOf", verbatim: "5,800x0.40 = 2,320 TOTAL GROSS PAYE = 9,680", marks: 2, contextNote: "The scheme shades 2,320 and 9,680 and prints 'Own figures shaded' beside them: take these two marks if both lines follow correctly from your own balance figure, even if your balance was wrong." },
    { id: "r-4", kind: "point", verbatim: "Tax Credits — 1700+1700 = 3,400", marks: 4, contextNote: "The scheme instructs: 'Award 2 marks if a candidate just uses ‘1700’'." },
    { id: "r-5", kind: "point", verbatim: "PAYE Due — 9,680 – 3400 = €6280", marks: 2, contextNote: "The 9,680 subtracted here is one of the figures the scheme shades as 'Own figures shaded', so take this mark if the subtraction is done correctly on your own Gross PAYE total, even if that total was wrong." },
    ],
